mapper.select:
SELECT id, user_id, txn_date, description, category, amount, currency, source_file, created_at
FROM transactions
WHERE user_id = #{userId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{yearMonth}
ORDER BY txn_date DESC, id DESC

SELECT category, SUM(amount) AS total_amount
FROM transactions
WHERE user_id = #{userId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{yearMonth}
GROUP BY category
ORDER BY total_amount DESC

SELECT COALESCE(SUM(amount), 0)
FROM transactions
WHERE user_id = #{userId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{yearMonth}
